// AgentsOptions configures the Agents API client: the Cloud API origin and a code:run key (or a person's token).
type AgentsOptions struct {
	ControlURL string
	APIKey     string
	Timeout    time.Duration
	Transport  http.RoundTripper
}

// Agents starts and drives Caveman Code sessions and agents (ADR 0131). The key's service account decides what it sees.
type Agents struct {
	endpoint, key string
	http          *http.Client
	stream        *http.Client
}

func NewAgents(options AgentsOptions) (*Agents, error) {
	u, err := url.Parse(options.ControlURL)
	if err != nil || u.User != nil || u.RawQuery != "" || u.Fragment != "" || u.Host == "" || (u.Scheme != "https" && !(u.Scheme == "http" && (u.Hostname() == "localhost" || u.Hostname() == "127.0.0.1" || u.Hostname() == "::1"))) {
		return nil, &Error{Code: "cave_endpoint_invalid", Message: "Use HTTPS or loopback HTTP without credentials, query, or fragment."}
	}
	if strings.TrimSpace(options.APIKey) == "" {
		return nil, &Error{Code: "cave_auth_required", Message: "A code:run key or access token is required."}
	}
	timeout := options.Timeout
	if timeout == 0 {
		timeout = 30 * time.Second
	}
	noRedirect := func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	return &Agents{endpoint: strings.TrimRight(u.String(), "/") + "/api/v1", key: options.APIKey,
		http:   &http.Client{Timeout: timeout, Transport: options.Transport, CheckRedirect: noRedirect},
		stream: &http.Client{Transport: options.Transport, CheckRedirect: noRedirect}}, nil
}

func agentsFailure(status int, body []byte) error {
	var envelope struct {
		Error struct{ Code, Message string } `json:"error"`
	}
	_ = json.Unmarshal(body, &envelope)
	if envelope.Error.Code == "" {
		envelope.Error.Code, envelope.Error.Message = "cave_request_failed", fmt.Sprintf("Request failed (%d).", status)
	}
	return &Error{Code: envelope.Error.Code, Message: envelope.Error.Message, Status: status}
}

func (a *Agents) call(ctx context.Context, method, path string, query url.Values, body, out any) error {
	target := a.endpoint + path
	if len(query) > 0 {
		target += "?" + query.Encode()
	}
	var reader io.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			return err
		}
		reader = bytes.NewReader(raw)
	}
	request, err := http.NewRequestWithContext(ctx, method, target, reader)
	if err != nil {
		return err
	}
	request.Header.Set("Authorization", "Bearer "+a.key)
	if body != nil {
		request.Header.Set("Content-Type", "application/json")
	}
	response, err := a.http.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	raw, err := io.ReadAll(io.LimitReader(response.Body, responseLimit+1))
	if err != nil {
		return err
	}
	if len(raw) > responseLimit {
		return &Error{Code: "cave_response_too_large", Message: "The response is larger than this SDK reads.", Status: response.StatusCode}
	}
	if response.StatusCode < 200 || response.StatusCode > 299 {
		return agentsFailure(response.StatusCode, raw)
	}
	if response.StatusCode == http.StatusNoContent {
		return nil
	}
	if err := json.Unmarshal(raw, out); err != nil {
		return &Error{Code: "cave_response_invalid", Message: "The response is not the documented JSON.", Status: response.StatusCode}
	}
	return nil
}

