// UploadFile uploads a file (at most 100 MB) the key's sessions may attach; it mounts read-only at
// /mnt/session/uploads/<name>.
func (a *Agents) UploadFile(ctx context.Context, name, mediaType string, content io.Reader) (CodeFile, error) {
	var out CodeFile
	if mediaType == "" {
		mediaType = "application/octet-stream"
	}
	if _, _, err := mime.ParseMediaType(mediaType); err != nil {
		return out, &Error{Code: "cave_media_type_invalid", Message: "The media type is not valid."}
	}
	body, writer := io.Pipe()
	form := multipart.NewWriter(writer)
	go func() {
		header := textproto.MIMEHeader{}
		header.Set("Content-Disposition", mime.FormatMediaType("form-data", map[string]string{"name": "file", "filename": name}))
		header.Set("Content-Type", mediaType)
		part, err := form.CreatePart(header)
		if err == nil {
			_, err = io.Copy(part, content)
		}
		if err == nil {
			err = form.Close()
		}
		_ = writer.CloseWithError(err)
	}()
	request, err := http.NewRequestWithContext(ctx, "POST", a.endpoint+"/code/files", body)
	if err != nil {
		_ = body.Close()
		return out, err
	}
	request.Header.Set("Authorization", "Bearer "+a.key)
	request.Header.Set("Content-Type", form.FormDataContentType())
	response, err := a.stream.Do(request)
	if err != nil {
		return out, err
	}
	defer response.Body.Close()
	raw, err := io.ReadAll(io.LimitReader(response.Body, responseLimit))
	if err != nil {
		return out, err
	}
	if response.StatusCode < 200 || response.StatusCode > 299 {
		return out, agentsFailure(response.StatusCode, raw)
	}
	if err := json.Unmarshal(raw, &out); err != nil {
		return out, &Error{Code: "cave_response_invalid", Message: "The response is not the documented JSON.", Status: response.StatusCode}
	}
	return out, nil
}

// DownloadFile writes a file's bytes to w.
func (a *Agents) DownloadFile(ctx context.Context, fileID string, w io.Writer) error {
	request, err := http.NewRequestWithContext(ctx, "GET", a.endpoint+"/code/files/"+url.PathEscape(fileID)+"/content", nil)
	if err != nil {
		return err
	}
	request.Header.Set("Authorization", "Bearer "+a.key)
	response, err := a.stream.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		raw, _ := io.ReadAll(io.LimitReader(response.Body, responseLimit))
		return agentsFailure(response.StatusCode, raw)
	}
	_, err = io.Copy(w, response.Body)
	return err
}

// StreamEvents calls each with a session's events after `after` (server-sent events) until the server ends the
// stream (15 minutes, or an ended session with nothing more), each returns an error, or ctx ends. Call again
// with the last seq to continue.
func (a *Agents) StreamEvents(ctx context.Context, sessionID string, after int64, each func(CodeStreamEvent) error) error {
	request, err := http.NewRequestWithContext(ctx, "GET", a.endpoint+"/code/sessions/"+url.PathEscape(sessionID)+"/events/stream?after="+strconv.FormatInt(after, 10), nil)
	if err != nil {
		return err
	}
	request.Header.Set("Authorization", "Bearer "+a.key)
	request.Header.Set("Accept", "text/event-stream")
	response, err := a.stream.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		raw, _ := io.ReadAll(io.LimitReader(response.Body, responseLimit))
		return agentsFailure(response.StatusCode, raw)
	}
	scanner := bufio.NewScanner(response.Body)
	scanner.Buffer(make([]byte, 64<<10), responseLimit)
	var seq, kind, data string
	kind = "message"
	for scanner.Scan() {
		line := scanner.Text()
		switch {
		case strings.HasPrefix(line, "id: "):
			seq = line[4:]
		case strings.HasPrefix(line, "event: "):
			kind = line[7:]
		case strings.HasPrefix(line, "data: "):
			data += line[6:]
		case line == "":
			if kind == "error" {
				var failure struct{ Code string }
				_ = json.Unmarshal([]byte(data), &failure)
				return &Error{Code: failure.Code, Message: "The event stream ended with an error."}
			}
			if seq != "" {
				n, err := strconv.ParseInt(seq, 10, 64)
				if err != nil {
					return &Error{Code: "cave_response_invalid", Message: "The event stream sent a malformed id."}
				}
				if err := each(CodeStreamEvent{Seq: n, Type: kind, Data: json.RawMessage(data)}); err != nil {
					return err
				}
			}
			seq, kind, data = "", "message", ""
		}
	}
	return scanner.Err()
}
